INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kommunikations-Modelle > Eisbergmodell
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Stellt das Eisbergmodell dar, dass nur ein kleiner Teil der Kommunikation sichtbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "Der sichtbare Teil ist nur die Spitze des Eisbergs"}, {"text": "Nein", "correct": false, "because": "Das Modell zeigt sichtbare und unsichtbare Anteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Eisbergmodell helfen, Missverständnisse in der Kommunikation zu erklären?', 2, '[{"text": "Ja", "correct": true, "because": "Es verdeutlicht versteckte Einflüsse"}, {"text": "Nein", "correct": false, "because": "Das Modell ist dafür geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der unsichtbare Teil des Eisbergs im Modell immer unwichtig für die Kommunikation?', 2, '[{"text": "Nein", "correct": true, "because": "Unsichtbare Faktoren wie Emotionen sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Der unsichtbare Teil ist maßgeblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können im Eisbergmodell Emotionen und Werte den Kommunikationsprozess beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Diese liegen unter der Oberfläche und wirken indirekt"}, {"text": "Nein", "correct": false, "because": "Emotionen und Werte sind zentrale Elemente"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Eisbergmodell nur auf verbale Kommunikation beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Es umfasst auch nonverbale und emotionale Aspekte"}, {"text": "Ja", "correct": false, "because": "Das Modell ist umfassender"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Teil des Eisbergmodells ist direkt sichtbar?', 3, '[{"text": "Die Spitze des Eisbergs", "correct": true, "because": "Repräsentiert Fakten und Worte"}, {"text": "Der Unterwasserteil", "correct": false, "because": "Versteckte Einflüsse"}, {"text": "Die Wasseroberfläche", "correct": false, "because": "Nur eine Grenze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element gehört laut Eisbergmodell zum unsichtbaren Bereich?', 2, '[{"text": "Emotionen", "correct": true, "because": "Liegen unter der Oberfläche"}, {"text": "Gesprochene Worte", "correct": false, "because": "Sind sichtbar"}, {"text": "Lautstärke", "correct": false, "because": "Wahrnehmbar, also sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Eisbergmodells in der Kommunikation?', 2, '[{"text": "Versteckte Einflüsse aufzeigen", "correct": true, "because": "Macht Unsichtbares bewusst"}, {"text": "Technische Details erklären", "correct": false, "because": "Nicht der Fokus"}, {"text": "Kommunikationszeit verkürzen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann laut Eisbergmodell Missverständnisse verursachen?', 3, '[{"text": "Ignorieren des unsichtbaren Teils", "correct": true, "because": "Emotionen und Werte übersehen"}, {"text": "Zu lautes Sprechen", "correct": false, "because": "Weniger relevant"}, {"text": "Zu schnelle Antwort", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metapher wird im Eisbergmodell verwendet, um die Kommunikation zu beschreiben?', 2, '[{"text": "Ein Eisberg", "correct": true, "because": "Symbolisiert sichtbare und unsichtbare Teile"}, {"text": "Ein Fluss", "correct": false, "because": "Nicht die Metapher"}, {"text": "Ein Baum", "correct": false, "because": "Falsches Bild"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören laut Eisbergmodell zum unsichtbaren Bereich?', 4, '[{"text": "Gefühle", "correct": true, "because": "Emotionale Ebene"}, {"text": "Werte", "correct": true, "because": "Persönliche Überzeugungen"}, {"text": "Erfahrungen", "correct": true, "because": "Beeinflussen Wahrnehmung"}, {"text": "Gesprochene Worte", "correct": false, "because": "Sichtbarer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Kommunikation erklärt das Eisbergmodell?', 3, '[{"text": "Versteckte Einflüsse", "correct": true, "because": "Unsichtbare Faktoren"}, {"text": "Emotionale Reaktionen", "correct": true, "because": "Unter der Oberfläche"}, {"text": "Kulturelle Unterschiede", "correct": true, "because": "Beeinflussen Kommunikation"}, {"text": "Technische Protokolle", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann das Eisbergmodell aufzeigen?', 4, '[{"text": "Missverständnisse durch Emotionen", "correct": true, "because": "Versteckte Gefühle"}, {"text": "Unklare Botschaften", "correct": true, "because": "Sichtbarer Teil unklar"}, {"text": "Konflikte durch Werte", "correct": true, "because": "Unsichtbare Differenzen"}, {"text": "Schnelle Kommunikation", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Eisbergmodell in der Kommunikation?', 3, '[{"text": "Bewusstsein für unsichtbare Faktoren", "correct": true, "because": "Macht Tiefe sichtbar"}, {"text": "Bessere Konfliktlösung", "correct": true, "because": "Verständnis fördern"}, {"text": "Verbesserte Empathie", "correct": true, "because": "Emotionen beachten"}, {"text": "Schnellere technische Lösungen", "correct": false, "because": "Nicht der Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kommunikationsaspekte deckt das Eisbergmodell ab?', 3, '[{"text": "Verbale Kommunikation", "correct": true, "because": "Sichtbarer Teil"}, {"text": "Nonverbale Kommunikation", "correct": true, "because": "Teilweise unsichtbar"}, {"text": "Emotionale Einflüsse", "correct": true, "because": "Unsichtbarer Bereich"}, {"text": "Hardwarefehler", "correct": false, "because": "Nicht kommunikationsbezogen"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Eisbergmodell zeigt, dass Emotionen die Kommunikation beeinflussen. b) Der sichtbare Teil ist der größte Anteil.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Emotionen ja, Unsichtbares dominiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der unsichtbare Teil des Eisbergs umfasst Werte und Überzeugungen. b) Das Modell ist nur für technische Kommunikation geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Werte ja, Modell allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Eisbergmodell kann Missverständnisse durch kulturelle Unterschiede erklären. b) Nur verbale Kommunikation wird betrachtet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kultur ja, auch nonverbal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das Eisbergmodell betont die Bedeutung des Unsichtbaren. b) Es ist ein technisches Modell für IT-Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unsichtbares ja, kein IT-Modell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Im Eisbergmodell sind Fakten der sichtbare Teil. b) Das Modell ignoriert nonverbale Kommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fakten ja, Nonverbal einbezogen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

